$run=Join-Path (Split-Path -Parent $PSScriptRoot) '.local/run'; if(!(Test-Path $run)){Write-Host 'Serviços SIGOV+ já estão parados.';exit 0}; foreach($name in 'api','web','worker'){$file="$run/$name.pid";if(Test-Path $file){$id=Get-Content $file -ErrorAction SilentlyContinue;$p=Get-Process -Id $id -ErrorAction SilentlyContinue;if($p){Stop-Process -Id $id;Write-Host "$name encerrado (PID $id)."}else{Write-Host "$name já estava parado."};Remove-Item $file -Force}}
